export const VEHICLE_TYPES = ["motorcycle", "car", "truck"] as const;
export type VehicleType = (typeof VEHICLE_TYPES)[number];

export function isVehicleType(x: unknown): x is VehicleType {
  return typeof x === "string" && (VEHICLE_TYPES as readonly string[]).includes(x);
}

// illustrative sketch, NOT in the repo
interface SpotSpec { size: SpotSize; charger: boolean }

function canUse(vehicle: VehicleType, needsCharging: boolean, spot: SpotSpec): boolean {
  if (!fits(vehicle, spot.size)) return false;   // existing physical rule
  if (needsCharging) return spot.charger;        // EV needs a charger
  return !spot.charger;                          // policy: keep chargers for EVs
}

// index: one heap per (size, charger) instead of per size
interface FreeSpots2 {
  nearest(size: SpotSize, charger: boolean): ParkingSpot | undefined;
