// real, src/parking-lot.ts
reserve(rawPlate: string, vehicle: VehicleType): Ticket {
  const plate = normalizePlate(rawPlate);
  if (!isVehicleType(vehicle)) {
    throw new ParkingError("INVALID_VEHICLE", `unknown vehicle type ${String(vehicle)}`);
  }
  if (this.ticketIdByPlate.has(plate)) {
    throw new ParkingError("ALREADY_PARKED", `${plate} is already inside or entering`);
  }
  if (!fittingSizes(vehicle).some((size) => this.index.nearest(size) !== undefined)) {
    throw new ParkingError("LOT_FULL", `no free spot for a ${vehicle}`);
  }
  const spot = this.allocation.choose(vehicle, this.index);
  if (spot === undefined || this.spotsById.get(spot.id) !== spot || !spot.isFree || !fits(vehicle, spot.size)) {
    throw new ParkingError("STRATEGY_BUG", `allocation strategy ${this.allocation.name} returned a spot that is not a free fitting one`);
  }

  // All checks passed; from here on nothing can fail.
  const ticket: Ticket = Object.freeze({
    id: randomUUID(),
    plate,
    vehicle,
    spotId: spot.id,
    level: spot.level,
    entryAt: this.clock.now(),
  });
  spot.reserve(ticket.id);
  this.entries.set(ticket.id, { ticket, status: "reserved", payments: [], penaltyMinor: 0 });
  this.ticketIdByPlate.set(plate, ticket.id);
  this.changeFree(spot, -1); // last: listeners see the finished change
  return ticket;
}

// real, src/pricing.ts constructor
constructor(ratesPerHourMinor: Record<VehicleType, number>, options: HourlyPricingOptions = {}) {
  for (const vehicle of VEHICLE_TYPES) {
    const rate = ratesPerHourMinor[vehicle];
    if (!Number.isSafeInteger(rate) || rate < 0) {
      throw new ParkingError("INVALID_RATE", `rate for ${vehicle} must be a non-negative integer in minor units`);
    }
  }
  const grace = options.graceMinutes ?? 0;
  if (!Number.isSafeInteger(grace) || grace < 0) {
    throw new ParkingError("INVALID_RATE", "graceMinutes must be a non-negative integer");
  }
  const cap = options.dailyCapHours;
  if (cap !== undefined && (!Number.isSafeInteger(cap) || cap < 1 || cap > 24)) {
    throw new ParkingError("INVALID_RATE", "dailyCapHours must be an integer from 1 to 24");
  }
  this.rates = { ...ratesPerHourMinor };
  this.graceMs = grace * MINUTE_MS;
  this.capHours = cap;
}

// real, src/allocation.ts
export function fittingSizes(vehicle: VehicleType): SpotSize[] {
  return SPOT_SIZES.filter((size) => fits(vehicle, size));
}

export function nearer(a: ParkingSpot, b: ParkingSpot): boolean {
  return a.level !== b.level ? a.level < b.level : a.position < b.position;
}

