// illustrative, NOT in the repo: a decorator that adds a flat night surcharge per started night hour,
// built on top of any PricingStrategy. Keeps all four invariants: integer, >= 0, pure, monotonic
// (base is monotonic and the surcharge only grows with the stay).
class NightSurcharge implements PricingStrategy {
  readonly name: string;
  constructor(private readonly base: PricingStrategy, private readonly perNightHourMinor: number) {
    if (!Number.isSafeInteger(perNightHourMinor) || perNightHourMinor < 0) {
      throw new ParkingError("INVALID_RATE", "surcharge must be a non-negative integer");
    }
    this.name = `${base.name}+night`;
  }
  fee(vehicle: VehicleType, entryAt: number, exitAt: number): number {
    const base = this.base.fee(vehicle, entryAt, exitAt); // throws INVALID_TIME first
    let nightHours = 0;
    for (let t = entryAt; t < exitAt; t += HOUR_MS) {
      const h = new Date(t).getUTCHours();
      if (h >= 22 || h < 6) nightHours++;
    }
    return base + nightHours * this.perNightHourMinor;
  }
}

